const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const menu=$('#product-menu'), product=$('.nav-product'), nav=$('.header nav'), toggle=$('.menu-toggle');
const groups=[['RUN YOUR PROPERTY',[['Reservations','reservations','Every stay, in view.'],['Front desk','front-desk','A warmer welcome.'],['Rooms','rooms','Know what is ready.'],['Housekeeping','housekeeping','Keep your team in sync.'],['Guests','guests','Remember the little details.']]],['GROW YOUR PROPERTY',[['Hotel website','websites','Your own beautiful front door.'],['Direct booking','booking','From discovery to confirmed.'],['Payments','payments','Get paid before arrival.'],['Analytics','analytics','Understand your property.']]],['CONNECT',[['Integrations','integrations','Bring your tools together.']]]];
menu.innerHTML=groups.map(([title,links])=>`<div><h3>${title}</h3>${links.map(([name,id,desc])=>`<a href="#${id}">${name}<small>${desc}</small></a>`).join('')}</div>`).join('');
function closeMenu(){menu.hidden=true;product.setAttribute('aria-expanded','false');nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}
product.onclick=()=>{menu.hidden=!menu.hidden;product.setAttribute('aria-expanded',String(!menu.hidden))};toggle.onclick=()=>{nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(nav.classList.contains('open')));if(!nav.classList.contains('open'))closeMenu()};
document.addEventListener('click',e=>{if(!e.target.closest('.header')||e.target.closest('.header a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
const dialog=document.createElement('dialog');dialog.setAttribute('aria-labelledby','dialog-title');$('#dialogs').append(dialog);
function showDialog(title,content){dialog.innerHTML=`<button class="close-dialog" aria-label="Close dialog">×</button><h2 id="dialog-title">${title}</h2>${content}`;dialog.querySelector('.close-dialog').onclick=()=>dialog.close();dialog.showModal()}
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
$$('[data-demo]').forEach(b=>b.onclick=()=>showDialog('Let’s talk hospitality.','<p>The demo booking connection is being prepared. Online appointments are not available in this preview yet.</p><p>Explore the product and plans while we get ready to welcome your property.</p><button class="button" id="view-plans">Explore plans →</button>')||($('#view-plans').onclick=()=>{dialog.close();$('#pricing').scrollIntoView()}));
const info={signin:['Your Sena workspace','Sign-in will be available through your property’s workspace once your account is set up. This website is a product preview.'],about:['Hospitality, beautifully run.','Sena brings reservations, rooms, guests, payments and your website together. Sena is a Nile Africa Technologies Ltd. company.'],careers:['Make room for what’s next.','Open roles will be shared here when available.'],guides:['A little guidance.','Explore the questions below for an introduction to Sena. Detailed product guides are being prepared.'],status:['System status','A live status page is not connected to this preview.'],privacy:['Privacy','The final privacy policy is being prepared for launch. These product previews use illustrative data and do not submit bookings or payments.'],terms:['Terms','Subscription terms will be provided before onboarding. Prices and plan details are shown on this page; payment provider and third-party fees may apply.']};
$$('[data-info]').forEach(b=>b.onclick=()=>{const [t,p]=info[b.dataset.info];showDialog(t,`<p>${p}</p>`)});
const stays={ada:['Ada James','23–25 September 2026','Executive 204','2 adults','Paid · ₦240,000','Direct','Upper floor preferred'],david:['David Okoro','24–28 September 2026','Executive 205','2 adults','Pay at property · ₦480,000','Booking.com','Evening arrival'],sarah:['Sarah Bello','23–25 September 2026','Deluxe 105','1 adult','Paid · ₦180,000','Walk-in','No notes'],tobi:['Tobi Ade','24–27 September 2026','Saffron Suite 301','2 adults','Paid · ₦540,000','Airbnb','No notes']};
$$('[data-reservation]').forEach(b=>b.onclick=()=>{const [name,...values]=stays[b.dataset.reservation];showDialog(name,`<p>Illustrative reservation</p><dl>${['Dates','Room','Guests','Payment','Source','Notes'].map((x,i)=>`<div><dt>${x}</dt><dd>${values[i]}</dd></div>`).join('')}</dl>`)});
const rooms=[['101','Clean','Executive'],['102','Occupied','Executive'],['103','Cleaning','Deluxe'],['104','Dirty','Deluxe'],['105','Maintenance','Deluxe'],['106','Clean','Executive']];
function renderRooms(filter='all'){const list=rooms.filter(r=>filter==='all'||(filter==='attention'?['Cleaning','Dirty','Maintenance'].includes(r[1]):r[1].toLowerCase()===filter));$('#room-grid').innerHTML=list.map(r=>`<div class="room-tile"><strong>${r[0]}</strong><small>${r[2]}</small><span>${r[1]}</span></div>`).join('');$('#room-count').textContent=`Showing ${list.length} of 6 rooms · Illustrative room statuses`}
renderRooms();$$('[data-filter]').forEach(b=>b.onclick=()=>{$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderRooms(b.dataset.filter)});
$$('[data-billing]').forEach(b=>b.onclick=()=>{$$('[data-billing]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});$$('[data-monthly]').forEach(x=>x.textContent='₦'+x.dataset[b.dataset.billing]);$$('.billing-period').forEach(x=>x.textContent=b.dataset.billing==='yearly'?'/ year':'/ month')});
$$('[data-checkin]').forEach(b=>b.onclick=()=>{b.disabled=true;b.textContent='Checked in ✓';$('#arriving-count').textContent=Number($('#arriving-count').textContent)-1;$('#inhouse-count').textContent=Number($('#inhouse-count').textContent)+1;$('#checkin-status').textContent=b.dataset.checkin+' checked in · Preview only'});
$$('[data-clean]').forEach(b=>b.onclick=()=>{const status=$('#clean-status-'+b.dataset.clean),detail=$('#clean-detail-'+b.dataset.clean);if(status.textContent==='To clean'){status.textContent='Cleaning';detail.textContent='Cleaning in progress';b.textContent='Mark clean ✓'}else{status.textContent='Clean';status.classList.remove('neutral');detail.textContent='Ready for the next guest';b.textContent='Room ready ✓';b.disabled=true}const remaining=$$('[data-clean]').filter(x=>!x.disabled).length;$('.housekeeping-phone>p:not(.eyebrow)').textContent=remaining?`${remaining} room${remaining>1?'s':''} need${remaining===1?'s':''} your attention`:'All rooms ready · Preview only'});
const booking=$('#booking-card'),initial=booking.innerHTML;function step(n){$$('[data-step]').forEach(x=>x.classList.toggle('active',Number(x.dataset.step)===n))}
function setupBooking(){const form=$('#availability-form');form.onsubmit=e=>{e.preventDefault();const data=new FormData(form);const nights=(Date.parse(data.get('checkout'))-Date.parse(data.get('checkin')))/86400000;if(!Number.isFinite(nights)||nights<1){$('#booking-error').textContent='Choose a check-out date after check-in.';return}const total=new Intl.NumberFormat('en-NG').format(nights*120000);step(1);booking.innerHTML=`<p class="mini-brand">THE STILL HOUSE · PREVIEW</p><h3>Executive Room</h3><p>₦120,000 / night · ${data.get('guests')}</p><p>${data.get('checkin')} → ${data.get('checkout')}</p><div class="booking-total"><span>${nights} night${nights>1?'s':''}</span><strong>₦${total}</strong></div><button class="button" id="reserve-preview">Preview confirmation →</button><button class="text-button" id="booking-back">Change dates</button>`;$('#booking-back').onclick=resetBooking;$('#reserve-preview').onclick=()=>{step(2);booking.innerHTML='<p class="mini-brand">THE STILL HOUSE · PREVIEW</p><h3>A warm welcome awaits.</h3><p>✓ Reservation confirmed</p><p>This is an example confirmation. No booking or payment has been made.</p><button class="button" id="booking-reset">Try again ↻</button>';$('#booking-reset').onclick=resetBooking}}}
function resetBooking(){booking.innerHTML=initial;step(0);setupBooking()}setupBooking();
